questionvariables.text:
/*Randomisation of the coefficients of the given functions*/
aa: rand_with_prohib(-5,5,[0]);
bb: rand_with_prohib(-7,7,[0]);
cc: rand_with_prohib(-8,8,[0]);
dd: rand_with_prohib(-6,6,[0]);

/*Defining the first randomised function denoted by z*/
f_numerator: aa*u;
f_denominator: bb*u^2+cc*v;
f_1: f_numerator/f_denominator;
/*Steps of expression of partial derivatives of z w.r.t u*/
ta_1a: expand(diff(f_numerator,u)*f_denominator- diff(f_denominator,u)*f_numerator),simp;/*expression of the numerator*/
ta_1b:  f_denominator^2/*expression of the denominator*/
ta_1: ta_1a/ta_1b; /*partial of z w.r.t u*/
/*Steps of expression of partial derivatives of z w.r.t v*/
ta_2a: expand(diff(f_numerator,v)*f_denominator- diff(f_denominator,v)*f_numerator),simp;/*expression of the numerator*/
ta_2b:  f_denominator^2; /*expression of the denominator*/
ta_2: ta_2a/ta_2b; /*partial of z w.r.t v*/
/*Defining the second randomised function denoted by g*/
g_numerator: aa*x*sin(bb*y);
g_denominator: dd*z^2;
g_xyz: g_numerator/g_denominator;

ta_3a: expand(diff(g_numerator,x)*g_denominator- diff(g_denominator,x)*g_numerator),simp;/*expression of the numerator*/
ta_3b:  g_denominator^2/*expression of the denominator*/
ta_3: ta_3a/ta_3b; /*partial derivative of of g w.r.t x*/

ta_4a: expand(diff(g_numerator,y)*g_denominator- diff(g_denominator,y)*g_numerator),simp;/*expression of the numerator*/
ta_4b:  g_denominator^2/*expression of the denominator*/
ta_4: ta_4a/ta_4b; /*partial derivative of of g w.r.t y*/

ta_5a: expand(diff(g_numerator,z)*g_denominator- diff(g_denominator,z)*g_numerator),simp;/*expression of the numerator*/
ta_5b:  g_denominator^2/*expression of the denominator*/
ta_5: ta_5a/ta_5b; /*partial derivative of of g w.r.t z*/

/*Defining the first randomised function denoted by z*/
assume(bb*x-cc*y^2>0);
fxy: aa*x^2+log(bb*x-cc*y^2);
assume(fxy>0);
h: sqrt(fxy);

/*Steps of expression of partial derivatives of h w.r.t x*/
ta_6a: (1/2)*(fxy^(-1/2)); 
ta_6b: diff(aa*x^2,x)+(diff(bb*x-cc*y^2,x)/(bb*x-cc*y^2));
ta_6: ta_6a*ta_6b;

/*Steps of expression of partial derivatives of h w.r.t y*/
ta_7a: (1/2)*(fxy^(-1/2)); 
ta_7b: diff(aa*x^2,y)+(diff(bb*x-cc*y^2,y)/(bb*x-cc*y^2));
ta_7: ta_7a*ta_7b;
